mapper.select:
SELECT COALESCE(SUM(CASE WHEN direction = 'IN' AND posting_type NOT IN ('SALES_RESERVE', 'SALES_RELEASE') THEN quantity ELSE 0 END), 0) AS inQuantity, COALESCE(SUM(CASE WHEN direction = 'OUT' AND posting_type NOT IN ('SALES_RESERVE', 'SALES_RELEASE') THEN quantity ELSE 0 END), 0) AS outQuantity, COALESCE(SUM(CASE WHEN posting_type = 'SALES_RESERVE' THEN quantity ELSE 0 END), 0) AS reserveQuantity, COALESCE(SUM(CASE WHEN posting_type = 'SALES_RELEASE' THEN quantity ELSE 0 END), 0) AS releaseQuantity FROM wms_stock_flow WHERE DATE(create_time) = CURDATE()
AND warehouse_id = #{warehouseId}
AND erp_tenant_id IN #{tid}

SELECT dates.date, COALESCE(SUM(CASE WHEN f.direction = 'IN' THEN f.quantity ELSE 0 END), 0) AS inQuantity, COALESCE(SUM(CASE WHEN f.direction = 'OUT' THEN f.quantity ELSE 0 END), 0) AS outQuantity FROM ( SELECT DATE_SUB(CURDATE(), INTERVAL n DAY) AS date FROM ( SELECT 0 AS n UNION SELECT 1 UNION SELECT 2 UNION SELECT 3 UNION SELECT 4 UNION SELECT 5 UNION SELECT 6 UNION SELECT 7 UNION SELECT 8 UNION SELECT 9 UNION SELECT 10 UNION SELECT 11 UNION SELECT 12 UNION SELECT 13 UNION SELECT 14 UNION SELECT 15 UNION SELECT 16 UNION SELECT 17 UNION SELECT 18 UNION SELECT 19 UNION SELECT 20 UNION SELECT 21 UNION SELECT 22 UNION SELECT 23 UNION SELECT 24 UNION SELECT 25 UNION SELECT 26 UNION SELECT 27 UNION SELECT 28 UNION SELECT 29 ) numbers WHERE n < #{days} ) dates LEFT JOIN wms_stock_flow f ON DATE(f.create_time) = dates.date
AND f.warehouse_id = #{warehouseId}
AND f.erp_tenant_id IN #{tid}
GROUP BY dates.date ORDER BY dates.date ASC
